def encrypt(text, n):
    if text is None or text == "" or n <= 0:
        return text

    result = text
    for _ in range(n):
        even_chars = result[1::2]
        odd_chars = result[0::2]
        result = even_chars + odd_chars
    return result

def decrypt(encrypted_text, n):
    if encrypted_text is None or encrypted_text == "" or n <= 0:
        return encrypted_text

    result = encrypted_text
    for _ in range(n):
        mid = len(result) // 2
        if len(result) % 2 == 0:
            left = result[:mid]
            right = result[mid:]
        else:
            left = result[:mid]
            right = result[mid + 1:]
            mid_char = result[mid]
            left = left + mid_char

        decrypted = []
        i = 0
        j = 0
        while i < len(right) or j < len(left):
            if i < len(right):
                decrypted.append(right[i])
                i += 1
            if j < len(left):
                decrypted.append(left[j])
                j += 1
        result = "".join(decrypted)
    return result
